// Fixture-only instrumentation. Never installs a global hook or dumps credentials.
import {createHash} from 'node:crypto';import {mkdir,writeFile} from 'node:fs/promises';import {join} from 'node:path';import {createRecorder} from '../../src/recorder/recorder.mjs';import {providerObservation} from '../../src/recorder/provider-observation.mjs';
export async function depthObservation(){
 const mode=process.env.C2C_DEPTH_RECORDER_MODE??'OFF',directory=process.env.C2C_DEPTH_TRACE_DIR,events=[],samples=[];let sequence=0;
 const ref=t=>t?createHash('sha256').update(JSON.stringify([t.provider,t.connectionId,t.accountId,t.bucketName,t.prefix])).digest('hex'):null;
 const trace=(stage,fields={})=>{if(directory){events.push({sequence:++sequence,monotonicMs:performance.now(),stage,...fields});if(events.length>4096)events.shift();}};
 const load=[];if(process.env.C2C_DEPTH_CPU_LOAD==='1'){const {Worker}=await import('node:worker_threads');for(let i=0;i<4;i++)load.push(new Worker(new URL('./bounded-cpu-load.mjs',import.meta.url),{workerData:{durationMs:8000}}));}
 const rows=new Map();let run=null;const rich={active:null,start:async p=>(run={id:crypto.randomUUID(),state:'ACTIVE',admitted:0,reserved:0,committed:0,limit:p.limit}),append:async e=>{run.committed+=e.length;return JSON.stringify(e).length;},stop:async(_id,state)=>(run.state=state,run),snapshot:async()=>run,runs:async()=>run?[run]:[],close(){}};
 const recorder=mode==='OFF'?null:createRecorder({basicFactory:async()=>({commit:async batch=>{for(const r of batch)rows.set(r.attemptId,r);return JSON.stringify(batch).length;},control:async()=>({capacity:4000,count:rows.size}),close(){}}),richFactory:async()=>rich});
 if(recorder){await recorder.ready;if(mode==='EXPANSIVE'){await recorder.setDebug(true);await recorder.start({limit:100000,consent:true});}}
 const observeClick=recorder?d=>{recorder.observe({stage:'CLICK_RECEIVED',attemptId:d.attemptId,monotonicMs:d.monotonicMs,providerId:d.row?.target?.provider,mode:d.row?.origin?.mode,context:'link'});return e=>recorder.observe({...e,attemptId:d.attemptId,proof:e.stage==='native.terminal'?providerObservation('cloudflare',e.result):undefined});}:undefined;
 return {trace,ref,observeClick,async click(registrar,info){const start=performance.now();trace('click.begin',{desired:registrar.inspect().desired?.generation,ack:registrar.inspect().acknowledgedGeneration,pending:registrar.inspect().pending});const out=await registrar.handleClick(info);const sample={state:out.state,code:out.code??null,elapsedMs:performance.now()-start};samples.push(sample);trace('click.end',sample);return out;},async finish(){await Promise.all(load.map(worker=>worker.terminate()));if(recorder){await recorder.drain();await recorder.stop();}if(directory){await mkdir(directory,{recursive:true});await writeFile(join(directory,'depth-plan-recovery.json'),JSON.stringify({evidenceClass:'NODE_FIXTURE_REAL_LOCAL_WORKERD_R2_NOT_CLOUDFLARE_MEMORY_RECORDER_PORTS',mode,loadWorkers:load.length,maxLoadMs:load.length?8000:0,events,samples,recorder:recorder?await recorder.status():null},null,2)+'\n');}recorder?.close();}};
}
